/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"ableton-level-3","number":3,"title":"Session View","skillBand":"Textbook","duration":"From the course textbook","summary":"- Section ID: ableton-sec-3-1 - Lessons Included: ableton-l3-1-1, ableton-l3-1-2","modules":[{"id":"ableton-m-3-1-1","code":"3.1","title":"Session View as an Instrument","blurb":"- Section ID: ableton-sec-3-1 - Lessons Included: ableton-l3-1-1, ableton-l3-1-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l3-1-1","title":"Section overview","blocks":[{"type":"step","title":"Section 3.1 — The Session Grid, Scenes & Status Fields","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-3-1</code>","<strong>Lessons Included:</strong> <code>ableton-l3-1-1</code>, <code>ableton-l3-1-2</code>","<strong>Target Skill Band:</strong> Non-Linear Improvisation &amp; Session Architecture","<strong>Manual Spine References:</strong> Chapter 7 (<em>Session View: 7.1–7.4</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Session Grid Mechanics"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Analyze the Session Matrix:</strong> Conceptualize Session View as a 2D musical matrix (Tracks as vertical instrument channels, Scenes as horizontal compositional sections).","<strong>Interpret Session Status Fields:</strong> Read clip and scene status indicators, including clip play states, loop markers, clip names, and launch quantization readouts.","<strong>Configure Scene Parameters:</strong> Edit scene names, scene-specific tempo values (e.g., <code>128 BPM</code>), and scene-specific time signatures (e.g., <code>3/4</code>) using <strong>Scene View</strong>.","<strong>Manipulate Clip Stop Buttons:</strong> Remove and restore Clip Stop buttons (<code>Ctrl+E</code>) in empty clip slots to enable continuous sustaining playback across scene transitions.","<strong>Configure \"Select on Launch\":</strong> Set workflow preferences to determine whether launching a clip automatically selects it in Clip View."],"ordered":true}]}],"minutes":8},{"id":"ableton-l3-1-1-2","title":"3.1.1: The Session Grid & Status Fields","blocks":[{"type":"step","title":"1.1 The Two-Dimensional Matrix Concept","blocks":[{"type":"prose","html":"Session View represents an elastic, non-linear musical canvas where structural arrangement is decoupled from fixed linear time:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          SESSION VIEW 2D MATRIX                             │\n├───────────────────┬──────────────┬──────────────┬──────────────┬────────────┤\n│ TRACKS (Columns)  │ Track 1 (Dr) │ Track 2 (Bs) │ Track 3 (Syn)│ MASTER /   │\n│ SCENES (Rows)     │ [Audio]      │ [MIDI]       │ [MIDI]       │ SCENE LAUNC│\n├───────────────────┼──────────────┼──────────────┼──────────────┼────────────┤\n│ Scene 1: \"Intro\"  │ [Clip 1: Dr] │ [Clip 1: Bs] │ [Clip 1: Pad]│ [ &gt; ] 120  │\n│ Scene 2: \"Verse\"  │ [Clip 2: Dr] │ [Clip 2: Bs] │ [Clip 2: Plk]│ [ &gt; ] 120  │\n│ Scene 3: \"Chorus\" │ [Clip 3: Dr] │ [Clip 3: Bs] │ [Clip 3: Ld] │ [ &gt; ] 124  │\n│ Scene 4: \"Outro\"  │ [   ■    ]   │ [Clip 4: Bs] │ [   ■    ]   │ [ &gt; ] 120  │\n├───────────────────┼──────────────┼──────────────┼──────────────┼────────────┤\n│ TRACK CONTROLS    │ [Stop All]   │ [Stop All]   │ [Stop All]   │ [Stop All] │\n└───────────────────┴──────────────┴──────────────┴──────────────┴────────────┘</pre>"},{"type":"list","items":["<strong>Vertical Track Columns:</strong> Each track can host multiple clip alternatives, but <strong>only one clip can play per track at any given moment</strong>.","<strong>Horizontal Scene Rows:</strong> A Scene represents a horizontal slice across all tracks. Launching a scene fires all clips situated on that row simultaneously."],"ordered":false}]},{"type":"step","title":"1.2 Clip Slot Status Indicators","blocks":[{"type":"prose","html":"Each clip slot in the grid displays specific visual feedback:"},{"type":"list","items":["<strong>Stopped / Loaded Clip:</strong> A colored rectangle displaying the clip name and a small play triangle (<code>&gt;</code>).","<strong>Playing Clip:</strong> A green flashing launch button with an animated pie-chart or linear loop progress indicator.","<strong>Triggered (Queued) Clip:</strong> A flashing play icon indicating the clip is queued and awaiting the next global launch quantization boundary (e.g., the next downbeat).","<strong>Recording Clip:</strong> A solid red circle indicating real-time recording is taking place in that slot.","<strong>Empty Slot with Stop Button:</strong> A square stop button (<code>■</code>)."],"ordered":false}]}],"minutes":8},{"id":"ableton-l3-1-2","title":"3.1.2: Stop Buttons, Scene Values & Scene View","blocks":[{"type":"step","title":"3.1.2: Stop Buttons, Scene Values & Scene View","blocks":[{"type":"heading","text":"2.1 Removing and Restoring Clip Stop Buttons","level":4},{"type":"prose","html":"By default, every empty clip slot contains a <strong>Clip Stop Button</strong> (<code>■</code>). When a scene is launched, any track with an empty slot on that row will immediately stop playing."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     CLIP STOP BUTTON BEHAVIOR                               │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  SCENE 1 (Intro):   [ Pad Loop (Playing) ]                                  │\n│                                │                                            │\n│  SCENE 2 (Verse):   CASE A: Standard Slot with Stop Button [ ■ ]            │\n│                             ──► Pad Loop STOPS when Scene 2 launches.       │\n│                                                                             │\n│                     CASE B: Slot with Stop Button REMOVED [   ]             │\n│                             ──► Pad Loop CONTINUES PLAYING uninterrupted    │\n│                                 when Scene 2 launches.                      │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Removing a Stop Button:</strong> Select an empty slot and press <code>Ctrl+E</code> (or right-click -&gt; <em>Remove Stop Button</em>).","<strong>Restoring a Stop Button:</strong> Select the empty slot and press <code>Ctrl+E</code> (or right-click -&gt; <em>Add Stop Button</em>)."],"ordered":false},{"type":"heading","text":"2.2 Scene Tempo & Time Signature Assignment","level":4},{"type":"prose","html":"Scenes can enforce automated tempo and meter changes when fired:"},{"type":"list","items":["<strong>Renaming Syntax:</strong> Rename a scene (<code>Ctrl+R</code>) and append tempo/meter values directly (e.g., <code>Chorus 128 BPM 3/4</code> or <code>Drop 140 BPM</code>).","<strong>Scene View (Live 12):</strong> When a Scene header is selected in the Master track, <strong>Scene View</strong> appears at the bottom of the interface, providing dedicated numeric fields for <strong>Scene Tempo</strong> (BPM) and <strong>Time Signature</strong>."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                                SCENE VIEW                                   │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [ Scene Name ]        Scene 3 - Bridge                                     │\n│  [ Scene Tempo ]       [x] 132.00 BPM   (Overrides project global tempo)    │\n│  [ Time Signature ]    [x] 3 / 4        (Overrides project global meter)    │\n│  [ Scene Color ]       [ Swatch Palette ]                                   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.3 Workflow Configuration: Select on Launch","level":4},{"type":"prose","html":"Under <code>Settings -&gt; Record / Warp / Launch</code>:"},{"type":"list","items":["<strong>Select on Launch (Enabled):</strong> Launching a clip automatically displays its contents in Clip View. Ideal for single-clip editing during live jamming.","<strong>Select on Launch (Disabled):</strong> Launching clips leaves Clip View focused on the currently selected clip, preventing UI focus jumping during live multi-track performance."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Constructing an 8-Scene Grid Matrix:</strong>","Create 4 tracks: <code>Drums</code> (Audio or Drum Rack), <code>Bass</code> (Drift), <code>Chords</code> (Analog/Operator), <code>Lead</code> (Drift).","Populate Scenes 1 through 8 with contrasting musical ideas.","Name each scene descriptively: <code>1-Intro</code>, <code>2-Verse A</code>, <code>3-Verse B</code>, <code>4-Build</code>, <code>5-Drop 1</code>, <code>6-Bridge</code>, <code>7-Drop 2</code>, <code>8-Outro</code>.","<strong>Stop Button Manipulation Drill:</strong>","On the <code>Chords</code> track, place a long 8-bar ambient pad in Scene 1 (<code>1-Intro</code>).","Leave Scene 2 (<code>2-Verse A</code>) empty on the <code>Chords</code> track.","Select the empty slot on Scene 2 of the <code>Chords</code> track and press <code>Ctrl+E</code> to remove its Stop Button.","Launch Scene 1. When playback reaches bar 5, launch Scene 2.","Verify that while the drums and bass switch to Verse clips, the ambient pad continues sustaining uninterrupted.","<strong>Scene Tempo Automation Drill:</strong>","Click the Scene 4 (<code>4-Build</code>) header in the Master track.","In Scene View at the bottom, enable <strong>Tempo</strong> and enter <code>128 BPM</code>.","Click the Scene 5 (<code>5-Drop 1</code>) header. In Scene View, enable <strong>Tempo</strong> and enter <code>134 BPM</code>.","Launch Scene 3 (120 BPM), then fire Scene 4, then Scene 5.","Watch the global BPM indicator in the Control Bar dynamically track each scene transition."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 3.0]\n[ ] Constructed an 8x4 Session grid with clear taxonomic naming.\n[ ] Removed and restored Clip Stop buttons using Ctrl+E.\n[ ] Successfully programmed a scene that transitions tempo upon launch via Scene View.\n[ ] Tested and configured 'Select on Launch' according to workflow preference.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 7 (<em>Session View: 7.1 Status Fields, 7.2 Tracks and Scenes, 7.3 Clip Stop Buttons, 7.4 Scene View</em>).","<strong>Ableton Knowledgebase:</strong> <em>Using Scene Tempo and Time Signatures in Live</em>, <em>Session View Clip Launching Best Practices</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-3-2-2","code":"3.2","title":"Session View as an Instrument","blurb":"- Section ID: ableton-sec-3-2 - Lessons Included: ableton-l3-2-1, ableton-l3-2-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l3-2-1","title":"Section overview","blocks":[{"type":"step","title":"Section 3.2 — Launch Modes, Quantization, Legato & Velocity Dynamics","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-3-2</code>","<strong>Lessons Included:</strong> <code>ableton-l3-2-1</code>, <code>ableton-l3-2-2</code>","<strong>Target Skill Band:</strong> Live Performance &amp; Real-Time Clip Manipulation","<strong>Manual Spine References:</strong> Chapter 16 (<em>Launching Clips: 16.1–16.6</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Clip Engine"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Differentiate the Four Clip Launch Modes:</strong> Analyze and implement <strong>Trigger</strong>, <strong>Gate</strong>, <strong>Toggle</strong>, and <strong>Repeat</strong> launch modes across audio and MIDI clips.","<strong>Configure Global vs. Clip Launch Quantization:</strong> Set global launch quantization in the Control Bar and apply per-clip launch quantization overrides (<code>None</code>, <code>1/16</code>, <code>1/4</code>, <code>1 Bar</code>, <code>8 Bars</code>).","<strong>Execute Legato Clip Switching:</strong> Implement <strong>Legato Mode</strong> to switch between clip variations seamlessly while preserving the relative playback playhead position.","<strong>Utilize Velocity Sensitivity &amp; Clip Nudge Controls:</strong> Map incoming trigger velocity to clip output amplitude, and apply real-time clip offset nudging to correct phase drift during live performance."],"ordered":true}]}],"minutes":8},{"id":"ableton-l3-2-1-2","title":"3.2.1: Launch Modes & Launch Quantization","blocks":[{"type":"step","title":"1.1 The Four Launch Modes","blocks":[{"type":"prose","html":"Clip launch behavior is configured in <strong>Clip View -&gt; Launch Section</strong> (accessible via the small launch panel icon in Clip View):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          CLIP LAUNCH MODES MATRIX                           │\n├───────────┬──────────────────────────────────┬──────────────────────────────┤\n│ MODE      │ MECHANICAL TRIGGER ACTION        │ MUSICAL USE CASE             │\n├───────────┼──────────────────────────────────┼──────────────────────────────┤\n│ Trigger   │ Mouse down/Key down starts clip. │ Standard song loops, backing │\n│ (Default) │ Plays to end or loops forever.   │ tracks, standard scenes.     │\n│           │ Mouse up/Key release is ignored. │                              │\n├───────────┼──────────────────────────────────┼──────────────────────────────┤\n│ Gate      │ Clip plays ONLY while button/key │ Instant stutter effects,     │\n│           │ is physically held down.         │ momentary vocal stabs,       │\n│           │ Release immediately stops clip.  │ performance fills.           │\n├───────────┼──────────────────────────────────┼──────────────────────────────┤\n│ Toggle    │ 1st click: Starts clip.          │ Solo performance beds,       │\n│           │ 2nd click: Stops clip.           │ drone layers, FX risers.     │\n├───────────┼──────────────────────────────────┼──────────────────────────────┤\n│ Repeat    │ Holds and continuously retriggers│ Trap hi-hat rolls, machine   │\n│           │ clip at the Quantization rate as │ gun fills, rapid stutter     │\n│           │ long as the button/key is held.  │ transitions.                 │\n└───────────┴──────────────────────────────────┴──────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Global vs. Per-Clip Launch Quantization","blocks":[{"type":"list","items":["<strong>Global Launch Quantization (Control Bar):</strong> Sets the master timing grid for launching all unassigned clips and scenes (Default: <code>1 Bar</code>).","<strong>Clip-Level Quantization Override:</strong> Located inside each clip's Launch panel. Setting this parameter to <code>None</code> allows instant, zero-latency finger-drumming triggers; setting it to <code>1/16</code> enables quantized stutter triggers."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                    LAUNCH QUANTIZATION TIMING RULER                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  Timeline:  1.1.1        1.2.1        1.3.1        1.4.1        2.1.1       │\n│               │            │            │            │            │         │\n│  User Click:  ▲ (Trigger at 1.1.3)                                │         │\n│               │                                                   │         │\n│  CASE A: Quantization = 1 Bar ────────────────────────────────────► [Plays] │\n│          (Clip waits for next downbeat at 2.1.1 before starting)            │\n│                                                                             │\n│  CASE B: Quantization = 1/4   ──────────► [Plays]                           │\n│          (Clip waits for next quarter note at 1.2.1 before starting)        │\n│                                                                             │\n│  CASE C: Quantization = None  ─► [Plays immediately at 1.1.3]               │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"ableton-l3-2-2","title":"3.2.2: Legato Mode, Velocity & Clip Nudge","blocks":[{"type":"step","title":"3.2.2: Legato Mode, Velocity & Clip Nudge","blocks":[{"type":"heading","text":"2.1 Legato Mode Mechanics","level":4},{"type":"prose","html":"When transitioning between two clip variations on the same track (e.g., <em>Bass Verse A</em> and <em>Bass Verse B</em>), standard launching forces the new clip to start from beat <code>1.1.1</code>."},{"type":"prose","html":"When <strong>Legato Mode</strong> is toggled <code>ON</code>:"},{"type":"list","items":["The newly launched clip inherits the exact <strong>internal playhead position</strong> of the clip currently playing.","If <em>Clip A</em> is playing at bar <code>3.2.1</code> when <em>Clip B</em> is launched, <em>Clip B</em> begins playing immediately from bar <code>3.2.1</code> of its own internal loop."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          LEGATO SWITCHING DYNAMICS                          │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  CLIP A (8-bar Bassline):  [Bar 1][Bar 2][Bar 3 ──► Playhead at 3.2.1]      │\n│                                                   │                         │\n│                                                   ▼ [Launch Clip B]         │\n│  CLIP B (With Legato ON):                 [Bar 3 (3.2.1)][Bar 4][Bar 5]...  │\n│  (Seamlessly continues the 8-bar harmonic progression without restarting)   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.2 Velocity Dynamics & Offset Nudge","level":4},{"type":"list","items":["<strong>Velocity Amount (0% to 100%):</strong> In the Launch panel, setting <strong>Velocity</strong> above <code>0%</code> scales the clip's audio gain or MIDI note velocity according to how hard the MIDI key/pad was struck when launched.","<strong>Clip Nudge (&lt; / &gt;):</strong> Located in the Clip View transport area. Pressing Nudge Left (<code>&lt;</code>) or Nudge Right (<code>&gt;</code>) momentarily accelerates or decelerates clip playback by a minute fraction to manually sync a drifting live source with an external turntable or unsynced drummer."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Four-Mode Comparison Drill:</strong>","Duplicate an active 1-bar drum loop across four Session slots on Track 1.","Open Clip View for Slot 1: Set Launch Mode to <code>Trigger</code>, Quantization to <code>1 Bar</code>.","Open Clip View for Slot 2: Set Launch Mode to <code>Gate</code>, Quantization to <code>1/16</code>.","Open Clip View for Slot 3: Set Launch Mode to <code>Toggle</code>, Quantization to <code>1 Bar</code>.","Open Clip View for Slot 4: Set Launch Mode to <code>Repeat</code>, Quantization to <code>1/16</code>.","Test each slot systematically using a mouse or MIDI pad:","Tap Slot 1 (verify continuous playback).","Hold Slot 2 for 2 beats, then release (verify instantaneous cut-off).","Tap Slot 3 once to start, tap again to stop.","Hold Slot 4 down (verify machine-gun 1/16th note repetition).","<strong>Legato Bassline Variation Drill:</strong>","On a MIDI Bass track, create an 8-bar walking bassline (<em>Bass_Main</em>).","Duplicate this clip into Slot 2 (<em>Bass_Variation</em>). Modify only bars 4 and 8 with octave stabs.","Enable <strong>Legato Mode</strong> in the Launch panel of both clips.","Set Quantization to <code>1 Bar</code>.","Launch <em>Bass_Main</em>. At bar 3.4, launch <em>Bass_Variation</em>.","Confirm that <em>Bass_Variation</em> takes over at bar 4.1 seamlessly without resetting to bar 1.1."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 3.1]\n[ ] Implemented and verified all four Launch Modes: Trigger, Gate, Toggle, Repeat.\n[ ] Configured and contrasted Global Quantization vs. Per-Clip Quantization.\n[ ] Programmed two related clips utilizing Legato Mode for seamless mid-phrase switching.\n[ ] Tested Velocity scaling on clip launching.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 16 (<em>Launching Clips: 16.1 Launch Modes, 16.2 Launch Quantization, 16.3 Legato Mode, 16.4 Velocity, 16.5 Nudge</em>).","<strong>Ableton Knowledgebase:</strong> <em>Clip Launch Modes in Depth</em>, <em>How Legato Mode Works</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-3-3-3","code":"3.3","title":"Session View as an Instrument","blurb":"- Section ID: ableton-sec-3-3 - Lessons Included: ableton-l3-3-1, ableton-l3-3-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l3-3-1","title":"Section overview","blocks":[{"type":"step","title":"Section 3.3 — Follow Actions & Generative Sequence Architecture","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-3-3</code>","<strong>Lessons Included:</strong> <code>ableton-l3-3-1</code>, <code>ableton-l3-3-2</code>","<strong>Target Skill Band:</strong> Algorithmic Sequencing &amp; Generative Composition","<strong>Manual Spine References:</strong> Chapter 16 (<em>Launching Clips: 16.7 Follow Actions</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Follow Action Engine"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Configure Follow Action Parameters:</strong> Program Follow Action time intervals (bars, beats, sixteenths) and link/unlink action time from clip loop length.","<strong>Implement Probabilistic Dual-Action Routing:</strong> Assign Action A and Action B triggers (<code>Next</code>, <code>Previous</code>, <code>First</code>, <code>Last</code>, <code>Any</code>, <code>Other</code>, <code>Play Again</code>, <code>Stop</code>, <code>Jump to Specific Clip</code>) and balance their statistical probability ratio.","<strong>Differentiate Follow Actions from MIDI Note Chance:</strong> Articulate the architectural boundary between <strong>Follow Actions</strong> (macro-level clip launching logic) and <strong>Note Probability</strong> (micro-level MIDI note triggering inside a clip).","<strong>Construct Generative Musical Topologies:</strong> Build deterministic cyclic sequences, stochastic fill generators, and evolving non-repetitive ambient beds."],"ordered":true}]}],"minutes":8},{"id":"ableton-l3-3-1-2","title":"3.3.1: Follow Action Mechanics & Probability Distribution","blocks":[{"type":"step","title":"1.1 The Follow Action Control Panel","blocks":[{"type":"prose","html":"Located in <strong>Clip View -&gt; Launch Section -&gt; Follow Action</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         FOLLOW ACTION CONTROL PANEL                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [ Follow Action Enable: ON ]                                               │\n│  Follow Action Time:  [ 2 ] Bars  [ 0 ] Beats  [ 0 ] Sixteenths             │\n│                                                                             │\n│  Action A: [ Next Clip   ]  ──► Probability Weight A: [ 70 ]                │\n│  Action B: [ Jump (Clip 4)] ──► Probability Weight B: [ 30 ]                │\n│                                                                             │\n│  Linked / Unlinked: [ Linked ]  (Locks Follow Action Time to Loop Length)   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Mathematical Probability Distribution","blocks":[{"type":"prose","html":"Live calculates the mathematical probability P(Action A) and P(Action B) using normalized integer weights:"},{"type":"prose","html":"P(Action A) = Weight AWeight A + Weight B"},{"type":"prose","html":"P(Action B) = Weight BWeight A + Weight B"},{"type":"prose","html":"For example, if Weight A = 70 and Weight B = 30, Action A fires with a deterministic 70% probability (0.70) and Action B fires with a 30% probability (0.30) upon expiration of the Follow Action Time."}]},{"type":"step","title":"1.3 Follow Action Target Commands","blocks":[{"type":"table","headers":["Command Name","Operational Trigger Behavior"],"rows":[["<strong>Stop</strong>","Stops playback on the track when action time expires."],["<strong>Play Again</strong>","Retriggers the current clip from its start marker or legato offset."],["<strong>Previous</strong>","Triggers the clip located immediately above in the track column."],["<strong>Next</strong>","Triggers the clip located immediately below in the track column."],["<strong>First</strong>","Triggers the topmost clip in the active Follow Action group."],["<strong>Last</strong>","Triggers the bottommost clip in the active Follow Action group."],["<strong>Any</strong>","Randomly selects any clip in the group (including the currently playing clip)."],["<strong>Other</strong>","Randomly selects any clip in the group <em>except</em> the currently playing clip."],["<strong>Jump</strong>","Jumps directly to a specifically designated clip slot index."]],"caption":null}]}],"minutes":8},{"id":"ableton-l3-3-2","title":"3.3.2: Architectural Topologies: Cycles, Fills & Generative Beds","blocks":[{"type":"step","title":"3.3.2: Architectural Topologies: Cycles, Fills & Generative Beds","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     THREE CORE GENERATIVE TOPOLOGIES                        │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  TOPOLOGY 1: DETERMINISTIC ROTATIONAL CYCLE (A -&gt; B -&gt; C -&gt; D -&gt; A)         │\n│  [Clip 1 (2 Bars)] ──(Next: 100%)──► [Clip 2 (2 Bars)] ──(Next: 100%)──┐    │\n│  ▲                                                                     │    │\n│  └───────────────────(First: 100%)── [Clip 4 (2 Bars)] ◄─(Next: 100%)──┘    │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  TOPOLOGY 2: STOCHASTIC MAIN + RARE FILL (85% Main / 15% Fill)              │\n│  [Main Beat (4 Bars)] ──► 85% [Play Again]                                  │\n│                       ──► 15% [Next (Fill Clip)]                            │\n│                                      │                                      │\n│  [Fill Clip (1 Bar)]  ──► 100% [First (Return to Main Beat)]                │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  TOPOLOGY 3: NON-REPETITIVE EVOLVING TEXTURE BED                            │\n│  [Pad A (3 Bars)] ──► [Other: 100%] ──► Selects B, C, or D randomly         │\n│  [Pad B (4 Bars)] ──► [Other: 100%] ──► Selects A, C, or D randomly         │\n│  [Pad C (5 Bars)] ──► [Other: 100%] ──► Selects A, B, or D randomly         │\n│  [Pad D (7 Bars)] ──► [Other: 100%] ──► Selects A, B, or C randomly         │\n│  (Polyrhythmic bar lengths produce an evolving, never-repeating background) │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.3 Follow Actions vs. MIDI Note Probability","level":4},{"type":"prose","html":"It is critical to maintain conceptual separation between sequencing layers:"},{"type":"list","items":["<strong>Follow Actions:</strong> Operate at the <strong>Clip Macro Layer</strong>. Governs which clip is launched on the track.","<strong>MIDI Note Chance:</strong> Operates at the <strong>Note Micro Layer</strong> inside the MIDI Note Editor. Governs whether individual notes (e.g., ghost snares or hi-hat rolls) trigger within a single clip."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Constructing an Infinite Drum Fill Machine:</strong>","Create a Drum Track with 4 consecutive clip slots:","Slot 1: <em>Main_Groove</em> (4 Bars)","Slot 2: <em>Snare_Fill</em> (1 Bar)","Slot 3: <em>Tom_Roll</em> (1 Bar)","Slot 4: <em>Cymbal_Crash</em> (1 Bar)","Configure <strong>Slot 1 (Main_Groove)</strong>:","Enable Follow Action. Set Time to <code>4.0.0</code>.","Action A: <code>Play Again</code> | Weight: <code>80</code>","Action B: <code>Any</code> | Weight: <code>20</code>","Configure <strong>Slots 2, 3, and 4</strong>:","Enable Follow Action. Set Time to <code>1.0.0</code>.","Action A: <code>First</code> | Weight: <code>100</code> (Forces immediate return to Main_Groove after fill).","Launch Slot 1. Listen over 32 bars. Verify that the groove loops naturally, intermittently executing randomized fills before automatically snapping back to the main groove.","<strong>Polyrhythmic Ambient Bed Drill:</strong>","On an Operator pad track, create three clips with prime-number bar lengths (3 bars, 5 bars, 7 bars).","In all three clips, set Follow Action to <code>Other</code> with Weight 100%.","Launch Clip 1. Verify continuous evolving ambient modulation without static loop repetition."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 3.2]\n[ ] Configured Follow Action Time in bars, beats, and sixteenths.\n[ ] Calculated and applied probabilistic weighting across Action A and Action B.\n[ ] Built a working stochastic drum fill system that reliably returns to Slot 1.\n[ ] Can clearly articulate the difference between Follow Actions and MIDI Note Chance.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 16 (<em>Launching Clips: 16.7 Follow Actions</em>).","<strong>Ableton Knowledgebase:</strong> <em>Follow Actions in Live 11 and 12</em>, <em>Generative Composition Techniques in Live</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-3-4-4","code":"3.4","title":"Session View as an Instrument","blurb":"- Section ID: ableton-sec-3-4 - Lessons Included: ableton-l3-4-1, ableton-l3-4-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l3-4-1","title":"Section overview","blocks":[{"type":"step","title":"Section 3.4 — The Session-to-Arrangement Bridge & Real-Time Performance Tracking","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-3-4</code>","<strong>Lessons Included:</strong> <code>ableton-l3-4-1</code>, <code>ableton-l3-4-2</code>","<strong>Target Skill Band:</strong> Compositional Printing &amp; View Handoff","<strong>Manual Spine References:</strong> Chapter 7 (<em>Session View: 7.5 Recording Sessions into the Arrangement</em>), Chapter 3 (<em>Live Concepts: 3.6 Tracks and Views</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Real-Time Capture Engine"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Execute Real-Time Performance Printing:</strong> Arm the Arrangement Record engine and capture an improvised multi-track Session View performance directly onto the Arrangement timeline.","<strong>Analyze Session-to-Arrangement Data Translation:</strong> Trace how clip launches, scene triggers, stop button events, mixer moves, and crossfader automation translate into discrete timeline clips and automation envelopes.","<strong>Master the Priority Override &amp; Back to Arrangement State:</strong> Diagnose why newly recorded Arrangement material becomes silent when Session clips are re-triggered, and execute restoration protocols deterministically."],"ordered":true}]}],"minutes":8},{"id":"ableton-l3-4-1-2","title":"3.4.1: Recording Session Performances into Arrangement","blocks":[{"type":"step","title":"1.1 The Printing Mechanism","blocks":[{"type":"prose","html":"Recording from Session View into Arrangement View is Live's bridge between non-linear improvisation and linear song structure:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                 SESSION TO ARRANGEMENT RECORDING PIPELINE                   │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  SESSION VIEW (Active Live Performance)                                     │\n│  [User launches Scene 1] ──► [Launches Scene 2] ──► [Launches Scene 3]      │\n│  (Real-time triggering of clips, mutes, solos, faders, and device knobs)    │\n│                                    │                                        │\n│                                    ▼ [Global Record Engine Active]          │\n│  ARRANGEMENT TIMELINE (Linear Result)                                       │\n│  Bar: 1.1                   17.1                  33.1                      │\n│  Trk 1: [─── Clip 1 ───────][─── Clip 2 ──────────][─── Clip 3 ────────────]│\n│  Trk 2: [─── Clip 1 ───────][─── Clip 2 ──────────][─── Clip 3 ────────────]│\n│  Fader: ─── -6dB ───────────\\────── -3dB ─────────/────── -6dB ─────────────│\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Non-Destructive Independence:</strong> Recording Session clips into the Arrangement <strong>does not delete or alter the original Session clips</strong>. Both views retain independent representations of the musical material connected through the track channels."],"ordered":false}]},{"type":"step","title":"1.2 What is Captured During the Performance Pass","blocks":[{"type":"list","items":["<strong>Clip Boundaries:</strong> Exact start, loop, and stop times corresponding to quantized launch moments.","<strong>Mixer Manipulation:</strong> Fader levels, track panning, mute/activate states, and crossfader assignments.","<strong>Continuous Automation:</strong> Macro knob movements, filter cutoff sweeps, and effect parameters on armed or automated tracks.","<strong>Tempo Changes:</strong> Scene tempo triggers are printed directly to the Arrangement Master track Tempo Automation Lane."],"ordered":true}]}],"minutes":8},{"id":"ableton-l3-4-2","title":"3.4.2: Session vs. Arrangement Priority Mechanics","blocks":[{"type":"step","title":"3.4.2: Session vs. Arrangement Priority Mechanics","blocks":[{"type":"heading","text":"2.1 The Two-State Playback Priority","level":4},{"type":"prose","html":"Following a recording pass, engineers often encounter confusion when editing the Arrangement:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        PRIORITY RESOLUTION WORKFLOW                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  SCENARIO: Arrangement has recorded clips across all tracks.                │\n│                                                                             │\n│  EVENT 1: User presses Spacebar in Arrangement View.                        │\n│  STATUS:  Arrangement is in full command. All tracks play timeline data.   │\n│                                                                             │\n│  EVENT 2: User triggers a Session clip on Track 2 (Bass).                   │\n│  STATUS:  Track 2 immediately switches to Session playback.                │\n│           Tracks 1, 3, and 4 continue playing Arrangement timeline data.    │\n│           Back to Arrangement Button lights up ORANGE.                     │\n│                                                                             │\n│  EVENT 3: User edits Arrangement clips on Track 2.                          │\n│  SYMPTOM: Edits are completely inaudible during playback because Track 2   │\n│           is still slaved to Session View!                                  │\n│                                                                             │\n│  REMEDY:  Press [F10] or click the Orange Back to Arrangement Button.       │\n│  STATUS:  Track 2 relinquishes Session playback and resyncs to timeline.   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.2 Location of Back to Arrangement Controls","level":4},{"type":"list","items":["<strong>Control Bar:</strong> The primary global Back to Arrangement button (orange rectangle with horizontal timeline stripes and a play triangle) appears to the right of the transport controls whenever an override is active.","<strong>Track Headers (Arrangement):</strong> Individual tracks show a small orange button on their track headers when that specific track is overridden.","<strong>Master Track (Session):</strong> An orange Back to Arrangement button appears at the top of the Master track in Session View."],"ordered":true}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Preparing the Multi-Track Performance:</strong>","Open your 8-scene Session Set from Section 3.1.","Stop all clips by clicking <strong>Stop All Clips</strong> on the Master track.","Press <code>Tab</code> to verify that Arrangement View is clear of conflicting material (or position the Arrangement insert marker at <code>1.1.1</code>).","<strong>Executing the Arrangement Recording Pass:</strong>","Press <code>Tab</code> to return to Session View.","Click the global <strong>Arrangement Record</strong> button in the Control Bar (<code>F9</code> or the solid round circle icon). Live begins recording immediately at <code>1.1.1</code>.","Launch Scene 1 (<code>1-Intro</code>). Let it play for 8 bars.","Launch Scene 2 (<code>2-Verse A</code>). Let it play for 8 bars.","While Scene 2 is playing, sweep the filter cutoff on your Drift synth.","Launch Scene 5 (<code>5-Drop 1</code>). Let it play for 16 bars.","Launch Scene 8 (<code>8-Outro</code>). Let it play to conclusion.","Press <code>Spacebar</code> to stop global recording.","<strong>Auditing and Restoring Timeline Authority:</strong>","Press <code>Tab</code> to switch to Arrangement View.","Observe the timeline: your improvised scene launches, clip transitions, and synth filter sweeps are now laid out as discrete linear clips and automation lanes.","Place the playhead at <code>1.1.1</code> and press <code>Spacebar</code>. Confirm full linear playback.","While playing, switch to Session View (<code>Tab</code>) and click the launch button on a stray drum loop.","Observe the orange <strong>Back to Arrangement</strong> indicator illuminating.","Press <code>F10</code> to immediately restore Arrangement timeline playback."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 3.3]\n[ ] Successfully executed an Arrangement Record pass from Session View.\n[ ] Verified that clips, mutes, and automation sweeps were faithfully transcribed to timeline.\n[ ] Created a deliberate Session override during timeline playback and identified the orange indicator.\n[ ] Restored full timeline playback authority using the F10 shortcut.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 7 (<em>Session View: 7.5 Recording Sessions into the Arrangement</em>), Chapter 3 (<em>Live Concepts: 3.6 Tracks and Views, 3.7 Routing</em>).","<strong>Ableton Knowledgebase:</strong> <em>Recording Session View to Arrangement View</em>, <em>Understanding Back to Arrangement</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
